const CoinStackRefund: React.FC<{ base: number; f: number; vfps: number }> = ({ base, f, vfps }) => {
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const coinD = base * 0.05;
  const N = 8;
  const KEEP = 2;
  const gapY = coinD * 0.5;
  const stackX = -base * 0.11;
  const bottomY = base * 0.085;
  const topY = bottomY - (N - 1) * gapY;
  const walletX = base * 0.13;
  const walletY = 0;
  const bracketX = stackX - coinD * 0.95;

  const plateP = springIn(f, vfps, 0, "LIQUID");
  const capP = springIn(f, vfps, 4, "LIQUID");
  const consume = interpolate(f, [66, 92], [0, 1], clamp);
  const glow = springIn(f, vfps, 152, "LIQUID");

  let bump = 0;
  for (let i = KEEP; i < N; i++) {
    const ri = springIn(f, vfps, 92 + (i - KEEP) * 4, "SNAPPY");
    bump += interpolate(ri, [0.8, 0.95, 1], [0, 0.05, 0], clamp);
  }
  const walletScale = Math.min(1.12, 1 + bump);

  const coins: React.ReactNode[] = [];
  for (let i = 0; i < N; i++) {
    const si = springIn(f, vfps, 14 + i * 3, "SNAPPY");
    let x = stackX;
    let y = bottomY - i * gapY + interpolate(si, [0, 1], [-coinD * 0.7, 0]);
    let scale = interpolate(si, [0, 1], [0.6, 1]);
    let op = Math.min(1, si * 5);
    const kept = i < KEEP;
    if (!kept) {
      const ri = springIn(f, vfps, 92 + (i - KEEP) * 4, "SNAPPY");
      if (ri > 0.001) {
        x = interpolate(ri, [0, 1], [stackX, walletX]);
        y = interpolate(ri, [0, 1], [bottomY - i * gapY, walletY]) - Math.sin(ri * Math.PI) * base * 0.06;
        scale = interpolate(ri, [0, 1], [1, 0.45]);
        op = interpolate(ri, [0.82, 1], [1, 0], clamp);
      }
    }
    coins.push(
      <div key={i} style={{ position: "absolute", left: "50%", top: "50%", zIndex: kept ? i : N - i, transform: `translate(calc(-50% + ${x}px), calc(-50% + ${y}px)) scale(${scale})`, opacity: op }}>
        <Coin d={coinD} base={base} dollar={i === N - 1} bright={kept && consume > 0.5} />
      </div>
    );
  }

  return (
    <div style={{ position: "relative", width: base * 0.5, height: base * 0.34 }}>
      <div style={{ position: "absolute", left: "50%", top: "50%", transform: `translate(calc(-50% + ${stackX}px), calc(-50% + ${bottomY + coinD * 0.5}px)) scaleX(${plateP})`, width: coinD * 1.7, height: coinD * 0.2, borderRadius: 999, background: C.card, border: `${Math.max(1, base * 0.0014)}px solid ${C.border}` }} />
      <div style={{ position: "absolute", left: "50%", top: "50%", transformOrigin: "bottom", transform: `translate(calc(-50% + ${bracketX}px), calc(-50% + ${(bottomY + topY) / 2}px)) scaleY(${capP})`, width: Math.max(2, base * 0.0024), height: bottomY - topY + coinD, background: ACCENT, opacity: 0.55 }} />
      <div style={{ position: "absolute", left: "50%", top: "50%", transform: `translate(calc(-50% + ${bracketX - coinD * 0.7}px), calc(-50% + ${topY - coinD * 0.6}px))`, fontFamily: F.marketing, fontWeight: 600, fontSize: coinD * 0.7, color: ACCENT, opacity: capP }}>$5</div>
      {coins}
      <div style={{ position: "absolute", left: "50%", top: "50%", zIndex: 10, transform: `translate(calc(-50% + ${walletX}px), calc(-50% + ${walletY}px)) scale(${walletScale})`, width: base * 0.13, height: base * 0.11, borderRadius: base * 0.016, background: C.card, border: `${Math.max(2, base * 0.0024)}px solid ${ACCENT}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <IconWallet s={base * 0.07} c={ACCENT} />
        <div style={{ position: "absolute", inset: -base * 0.01, borderRadius: base * 0.02, border: `${Math.max(2, base * 0.0024)}px solid ${ACCENT}`, opacity: interpolate(glow, [0, 1], [0, 0.5]) * (1 - glow) * 2, transform: `scale(${interpolate(glow, [0, 1], [0.9, 1.15])})` }} />
      </div>
    </div>
  );
};

const TILE_ICONS: React.FC<IconProps>[] = [
