const StreamTile: React.FC<{ base: number; tile: number; Icon: React.FC<IconProps>; lit: number }> = ({ base, tile, Icon, lit }) => (
  <div style={{ position: "relative", width: tile, height: tile, borderRadius: base * 0.014, background: C.card, border: `${Math.max(2, base * 0.0018)}px solid ${C.border}`, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${1 + lit * 0.06})` }}>
