    <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.014, border: `${Math.max(2, base * 0.0022)}px solid ${ACCENT}`, opacity: lit }} />
    <Icon s={tile * 0.5} c={lit > 0.5 ? ACCENT : C.textSubtle} sw={2} />
