);

const CatalogStream: React.FC<{ base: number; width: number; height: number; f: number; vfps: number; countIn: number }> = ({ base, width, height, f, vfps, countIn }) => {
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const cols = 5;
  const tile = base * 0.092;
  const pitch = tile * 1.28;
  const colGap = base * 0.03;
  const bandH = height * 0.68;
  const K = Math.ceil(bandH / pitch) + 2;
  const totalH = K * pitch;
  const speed = pitch / 54;
  const bandW = cols * tile + (cols - 1) * colGap;
  const bandIn = springIn(f, vfps, 4, "LIQUID");
  const contactY = bandH / 2;
  const beamOn = interpolate(f, [40, 62], [0, 1], clamp);
  const coinIn = springIn(f, vfps, 24, "ELASTIC");
  const coinX = width * 0.5;
  const bandRight = width * 0.055;
  const bandLeftX = width - bandRight - bandW;
  const centerY = height / 2;
  const flash = interpolate(f, [10, 18, 30], [0, 1, 0], clamp);

  const columns: React.ReactNode[] = [];
  for (let c = 0; c < cols; c++) {
    const dir = c % 2 === 0 ? 1 : -1;
    const distC = Math.abs(c - (cols - 1) / 2);
    const colScale = 1 - distC * 0.07;
    const colOp = (1 - distC * 0.17) * bandIn;
    const tiles: React.ReactNode[] = [];
    for (let i = 0; i < K; i++) {
      const yRaw = (((i * pitch - f * speed * dir) % totalH) + totalH) % totalH;
      const y = yRaw - pitch;
      const prox = Math.max(0, 1 - Math.abs(y + tile / 2 - contactY) / (pitch * 0.6));
      const lit = prox * beamOn;
      const Icon = TILE_ICONS[(c * 5 + i) % TILE_ICONS.length];
      tiles.push(
        <div key={i} style={{ position: "absolute", left: 0, top: y, width: tile, height: tile }}>
          <StreamTile base={base} tile={tile} Icon={Icon} lit={lit} />
        </div>
      );
    }
    columns.push(
      <div key={c} style={{ position: "relative", width: tile, height: bandH, opacity: colOp, transform: `scale(${colScale})`, transformOrigin: "center" }}>
        {tiles}
      </div>
    );
  }

  return (
    <>
      <div style={{ position: "absolute", left: width * 0.09, top: "50%", transform: `translateY(calc(-50% + ${interpolate(countIn, [0, 1], [20, 0])}px))`, opacity: countIn, display: "flex", flexDirection: "column", gap: base * 0.006 }}>
        <span style={{ fontFamily: F.marketing, fontWeight: 600, fontSize: base * 0.17, color: C.text, letterSpacing: "-0.04em", lineHeight: 0.9 }}>
          1,000<span style={{ color: ACCENT, display: "inline-block", transform: `scale(${1 + flash * 0.12})` }}>s</span>
        </span>
        <span style={{ fontFamily: F.primary, fontWeight: 500, fontSize: base * 0.032, color: C.textMuted }}>AI tools</span>
      </div>
      <div style={{ position: "absolute", left: coinX, top: centerY, height: Math.max(2, base * 0.0026), width: bandLeftX - coinX, background: ACCENT, opacity: 0.5 * beamOn, transformOrigin: "left", transform: `translateY(-50%) scaleX(${beamOn})` }} />
      <div style={{ position: "absolute", left: coinX, top: centerY, transform: `translate(-50%, -50%) scale(${interpolate(coinIn, [0, 1], [0.6, 1])})`, opacity: Math.min(1, coinIn * 4), width: base * 0.12, height: base * 0.12, borderRadius: "50%", background: C.card, border: `${Math.max(3, base * 0.003)}px solid ${ACCENT}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontFamily: F.marketing, fontWeight: 600, fontSize: base * 0.034, color: C.text, letterSpacing: "-0.02em" }}>x<span style={{ color: ACCENT }}>402</span></span>
      </div>
      <div style={{ position: "absolute", right: bandRight, top: "50%", transform: "translateY(-50%)", height: bandH, width: bandW, display: "flex", gap: colGap, WebkitMaskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 13%, rgba(0,0,0,1) 87%, rgba(0,0,0,0) 100%)", maskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 13%, rgba(0,0,0,1) 87%, rgba(0,0,0,0) 100%)" }}>
        {columns}
      </div>
    </>
  );
};

// Root wrapper — transparent canvas + fonts. Each scene fills it.
const SceneRoot: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <AbsoluteFill>
    <style>{BRAND_FONT_FACE_CSS}</style>
    {children}
  </AbsoluteFill>
);

// Standalone demo callout — opaque chip, full orange stroke + icon. Enters and HOLDS.
const CalloutScene: React.FC<{ icon: string; main: string; accent?: string; mono?: boolean }> = ({ icon, main, accent, mono }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const enter = springIn(frame, vfps, 0, "SNAPPY");
  const iconPop = springIn(frame, vfps, 6, "ELASTIC");
  const ty = interpolate(enter, [0, 1], [base * 0.05, 0]);
  const sc = interpolate(enter, [0, 1], [0.95, 1]);
  const Ic = ICON_MAP[icon] || IconTerminal;
  return (
    <SceneRoot>
      <div style={{ position: "absolute", left: width * 0.055, bottom: height * 0.11, display: "flex", alignItems: "center", gap: base * 0.024, padding: `${base * 0.026}px ${base * 0.034}px`, background: C.card, border: `${Math.max(3, base * 0.0032)}px solid ${ACCENT}`, borderRadius: base * 0.02, opacity: Math.min(1, enter * 4), transform: `translateY(${ty}px) scale(${sc})`, filter: `blur(${interpolate(enter, [0, 1], [5, 0])}px)` }}>
        <div style={{ ...pop(iconPop), display: "flex" }}>
          <Ic s={base * 0.07} c={ACCENT} sw={2.2} />
        </div>
        <span style={{ fontFamily: mono ? "ui-monospace, 'SF Mono', Menlo, monospace" : F.marketing, fontWeight: 600, fontSize: base * 0.058, color: C.text, letterSpacing: "-0.02em", lineHeight: 1, whiteSpace: "nowrap" }}>
          {main}
          {accent && <span style={{ color: ACCENT }}> {accent}</span>}
        </span>
      </div>
    </SceneRoot>
  );
